<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useApi} from '../../../../shared/api';import {confirmDanger} from '../../../../shared/components/DangerConfirm';
const emit=defineEmits<{changed:[];reset:[]}>();const api=useApi();const context=ref<any>();const error=ref('');const busy=ref(false);
const actor=computed(()=>context.value?.actors?.find((item:any)=>item.id===context.value.currentActorId));
async function load(){try{context.value=await api('/admin/business/context');error.value='';}catch(problem){error.value=problem instanceof Error?problem.message:'目录加载失败';}}
async function switchActor(actorId:string){busy.value=true;try{await api('/admin/business/actor','POST',{actorId});await load();emit('changed');}catch(problem){error.value=problem instanceof Error?problem.message:'切换失败';}finally{busy.value=false;}}
async function permission(permissionCode:string,enabled:boolean){busy.value=true;try{await api('/admin/business/permissions','POST',{actorId:actor.value.id,permissionCode,enabled});await load();emit('changed');}catch(problem){error.value=problem instanceof Error?problem.message:'变更失败';}finally{busy.value=false;}}
onMounted(load);defineExpose({load});
async function restoreBusiness(){if(!(await confirmDanger({title:'恢复业务数据',message:'恢复业务账号、权限和申请的初始数据？已有未完成申请将取消。',confirmText:'恢复'})))return;busy.value=true;try{await api('/admin/business/reset','POST',{});await load();emit('reset');emit('changed')}catch(problem){error.value=problem instanceof Error?problem.message:'恢复失败'}finally{busy.value=false}}
</script>
<template><section class="business-context"><div class="row"><strong>当前业务身份</strong><el-select :model-value="context?.currentActorId" :disabled="busy" @update:model-value="switchActor"><el-option v-for="item in context?.actors||[]" :key="item.id" :value="item.id" :label="item.name" /></el-select><el-button text @click="load">刷新目录</el-button><el-button text :disabled="busy" @click="restoreBusiness">恢复业务数据</el-button></div><p v-if="actor" class="muted">角色：{{actor.roles?.join('、')}} · 部门：{{context.departments?.find((item:any)=>item.id===actor.departmentId)?.name||actor.departmentId}}</p><details v-if="context"><summary>查看业务目录、权限与申请</summary><el-tabs><el-tab-pane label="用户"><el-table :data="context.users" max-height="260"><el-table-column prop="id" label="用户ID" /><el-table-column prop="name" label="名称" /><el-table-column prop="departmentId" label="部门" /><el-table-column prop="status" label="状态" /></el-table></el-tab-pane><el-tab-pane label="部门 / 角色"><pre>{{JSON.stringify({departments:context.departments,roles:context.roles},null,2)}}</pre></el-tab-pane><el-tab-pane label="当前身份权限"><p v-for="item in context.permissions||[]" :key="item.code||item.id" class="row"><span>{{item.name||item.code||item.id}}</span><el-switch :model-value="actor?.permissions?.includes(item.code||item.id)" :disabled="busy" @update:model-value="permission(item.code||item.id,Boolean($event))" /></p></el-tab-pane><el-tab-pane label="变更申请"><pre>{{JSON.stringify(context.requests,null,2)}}</pre></el-tab-pane></el-tabs></details><p v-if="error" class="error" role="alert">{{error}}</p></section></template>
<style scoped>.business-context{padding:.8rem;border:1px solid var(--line);border-radius:.5rem}.business-context .el-select{width:20rem}.business-context pre{max-height:18rem;overflow:auto;white-space:pre-wrap}.business-context summary{cursor:pointer}</style>
